func autoMigrateStaticSymbolConfig(ctx context.Context, old v12.StaticSymbolConfig) (StaticSymbolConfig, error) {
	var strokeColor *color.Color
	if old.StrokeColor != nil {
		v, err := color.MigrateColor(ctx, *old.StrokeColor)
		if err != nil {
			return StaticSymbolConfig{}, err
		}
		strokeColor = &v
	}
	return StaticSymbolConfig{
		LabeledConfig: old.LabeledConfig,
		ScaledConfig:  old.ScaledConfig,
		StrokeColor:   strokeColor,
	}, nil
}

func autoMigrateToggleSymbolConfig(ctx context.Context, old v12.ToggleSymbolConfig) (ToggleSymbolConfig, error) {
	toggleConfig, err := MigrateToggleConfig(ctx, old.ToggleConfig)
	if err != nil {
		return ToggleSymbolConfig{}, err
	}
	var strokeColor *color.Color
	if old.StrokeColor != nil {
		v, err := color.MigrateColor(ctx, *old.StrokeColor)
		if err != nil {
			return ToggleSymbolConfig{}, err
		}
		strokeColor = &v
	}
	return ToggleSymbolConfig{
		ToggleConfig: toggleConfig,
		StrokeColor:  strokeColor,
	}, nil
}

func autoMigrateStalenessConfig(ctx context.Context, old v12.StalenessConfig) (StalenessConfig, error) {
	var stalenessColor *color.Color
	if old.StalenessColor != nil {
		v, err := color.MigrateColor(ctx, *old.StalenessColor)
		if err != nil {
			return StalenessConfig{}, err
		}
		stalenessColor = &v
	}
	return StalenessConfig{
		StalenessTimeout: old.StalenessTimeout,
		StalenessColor:   stalenessColor,
	}, nil
}

func autoMigrateStateMapping(ctx context.Context, old v12.StateMapping) (StateMapping, error) {
	var colorVal *color.Color
	if old.Color != nil {
		v, err := color.MigrateColor(ctx, *old.Color)
		if err != nil {
			return StateMapping{}, err
		}
		colorVal = &v
	}
	return StateMapping{
		Key:   old.Key,
		Name:  old.Name,
		Value: old.Value,
		Color: colorVal,
	}, nil
}

